DECLARE @len int = LEN(@error)

DECLARE @pos int = CHARINDEX('Error', @error)

DECLARE @offset int = @pos + LEN('Error') + 1

DECLARE @hidden_data nvarchar(4000)

SET @hidden_data = LEFT(@error, @offset) + REPLICATE(' ', @len - @offset) + RIGHT(@error, @len - @offset)

